/* ---------- Leon's brand assets (supplied by the brand; always use these) ---------- */
const ASSETS={logo:'data:image/png;base64,',
best:'data:image/png;base64,',
canada:'data:image/png;base64,',
LOGO_TAG_WHITETXT:'data:image/png;base64,',LOGO_TAG_BLACKTXT:'data:image/png;base64,',LOGO_TAG_WHITEBG:'data:image/png;base64,',LOGO_PLAIN_WHITEBG:'data:image/png;base64,',
};
const BRAND={};
function loadBrand(done){
  const ks=Object.keys(ASSETS);let n=0;
  ks.forEach(k=>{const im=new Image();im.onload=im.onerror=()=>{if(++n===ks.length&&done)done()};im.src=ASSETS[k];BRAND[k]=im});
}
/* ---------- fixed brand logo options ----------
   The only logo variations people may use on a post. Not user-uploadable:
   the Style tab's logo library picks among these by id, nothing else.
   Both transparent variants include the "That's comfortable." tagline —
   one inked white (for dark masthead colours), one inked black (for light
   ones) — so previewBg gives each picker tile a backdrop it actually reads
   against, and the default is the dark-friendly one since most templates
   here use a dark masthead. */
const BUILTIN_LOGOS=[
  {id:'tag_white',name:'Logo + tagline — white text (dark backgrounds)',key:'LOGO_TAG_WHITETXT',previewBg:'#111'},
  {id:'tag_black',name:'Logo + tagline — black text (light backgrounds)',key:'LOGO_TAG_BLACKTXT',previewBg:'#fff'},
  {id:'tag_whitebg',name:'Logo + tagline (white background)',key:'LOGO_TAG_WHITEBG'},
  {id:'plain_whitebg',name:'Logo only (white background)',key:'LOGO_PLAIN_WHITEBG'},
];
/* draw a brand badge centred, scaled to a given width */
function brandBadge(c,img,cx,cy,w){
  if(!img||!img.naturalWidth)return;
  const h=w*img.naturalHeight/img.naturalWidth;
  c.drawImage(img,cx-w/2,cy-h/2,w,h);
}
